(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0]).click();
  await sleep(3000);
  return JSON.stringify({ title: document.querySelector('.pj-title')?.textContent || null, buttons: [...document.querySelectorAll('.pj-head-actions > button')].map((b) => b.textContent.trim()).join(' | ') });
})()
